import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

// Simple test components
const Dashboard = () => <div><h1>🏠 Dashboard</h1><p>E-REDES Bot funcionando!</p></div>;
const Simulation = () => <div><h1>⚙️ Simulação</h1><p>Página de configuração</p></div>;
const Results = () => <div><h1>📊 Resultados</h1><p>Página de resultados</p></div>;
const Settings = () => <div><h1>⚙️ Configurações</h1><p>Página de definições</p></div>;

function App() {
  return (
    <Router>
      <div className="app" style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
        <nav style={{ marginBottom: '20px', borderBottom: '1px solid #ccc', paddingBottom: '10px' }}>
          <a href="/" style={{ marginRight: '15px' }}>Dashboard</a>
          <a href="/simulation" style={{ marginRight: '15px' }}>Simulação</a>
          <a href="/results/test" style={{ marginRight: '15px' }}>Resultados</a>
          <a href="/settings" style={{ marginRight: '15px' }}>Configurações</a>
        </nav>

        <main className="main-content">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/simulation" element={<Simulation />} />
            <Route path="/results/:id" element={<Results />} />
            <Route path="/settings" element={<Settings />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
}

export default App;
